            'id': int(row['id']),
            'year': int(row['year']),
            'type': row['type'].strip(),
            'question': row['question'].strip()
        })

years = sorted(set(r['year'] for r in rows))
types = ['MCQs', 'Short', 'Long']
total = len(rows)

# ── KPI: Total questions per year ──
per_year = Counter(r['year'] for r in rows)
yearly_counts = {y: per_year.get(y, 0) for y in years}

# ── KPI: By type per year ──
type_year = defaultdict(lambda: defaultdict(int))
for r in rows:
    type_year[r['year']][r['type']] += 1

# ── KPI: Overall type breakdown ──
type_total = Counter(r['type'] for r in rows)

# ── KPI: YoY change ──
yoy = []
sorted_years = sorted(yearly_counts.keys())
for i in range(1, len(sorted_years)):
    prev_y = sorted_years[i-1]
    curr_y = sorted_years[i]
    prev_c = yearly_counts[prev_y]
    curr_c = yearly_counts[curr_y]
    change = curr_c - prev_c
    pct = (change / prev_c * 100) if prev_c else 0
    yoy.append({'from': prev_y, 'to': curr_y, 'prev': prev_c, 'curr': curr_c, 'change': change, 'pct': round(pct, 1)})

# ── KPI: Avg questions per type ──
avg_per_type = {}
for t in types:
    counts = [type_year[y][t] for y in years]
    avg_per_type[t] = round(sum(counts) / len(counts), 1)

# ── Topic/keyword analysis ──
STOPWORDS = set(['the','a','an','is','are','was','were','in','on','at','to','for','of','and','or',
    'this','that','it','its','with','by','from','as','be','not','what','which','how',
    'do','does','did','will','would','can','could','shall','should','may','might',
    'if','then','else','there','their','they','them','them','he','she','we','you',
    'i','me','my','your','our','his','her','have','has','had','been','being','also',
    'any','each','into','through','during','before','after','above','below','between',
    'out','up','down','all','more','most','other','some','such','no','nor','only',
    'same','so','than','too','very','just','because','but','about','one','two',
    'three','four','five','six','seven','eight','nine','ten','give','given','use',
    'used','using','write','define','explain','following','called','statement',
    'program','example','within','answer','without','many','when','where','why',
    'void','main','int','float','char','double','printf','scanf','getch','clrscr',
    'print','need','known','find','means','these','those','every','among'])

def extract_keywords(text):
    text = text.lower()
    text = re.sub(r'[^a-z\s]', ' ', text)
    words = text.split()
    return [w for w in words if len(w) > 2 and w not in STOPWORDS]

# Overall keyword frequency
all_keywords = []
for r in rows:
    all_keywords.extend(extract_keywords(r['question']))
keyword_freq = Counter(all_keywords).most_common(30)

# Keywords by type
keywords_by_type = {}
for t in types:
    kws = []
    for r in rows:
        if r['type'] == t:
            kws.extend(extract_keywords(r['question']))
    keywords_by_type[t] = Counter(kws).most_common(15)

# Keywords by year
keywords_by_year = {}
for y in years:
    kws = []
    for r in rows:
        if r['year'] == y:
            kws.extend(extract_keywords(r['question']))
    keywords_by_year[y] = Counter(kws).most_common(10)

# ── Topic categories ──
TOPIC_CATEGORIES = {
    'Loops & Iteration': ['loop', 'for', 'while', 'iteration', 'nested', 'dowhile', 'counter'],
    'Control Structures': ['switch', 'case', 'break', 'continue', 'else', 'conditional', 'selection', 'goto', 'ladder'],
    'Data Types & Variables': ['variable', 'constant', 'data', 'type', 'integer', 'string', 'character', 'size', 'bytes', 'precision', 'range'],
    'Operators': ['operator', 'arithmetic', 'relational', 'logical', 'assignment', 'precedence', 'unary', 'ternary', 'increment', 'decrement', 'modulus', 'bitwise'],
    'Functions': ['function', 'recursive', 'recursion', 'prototype', 'return', 'parameter', 'calling', 'library'],
    'I/O & Format Specifiers': ['format', 'specifier', 'escape', 'sequence', 'input', 'output', 'gets', 'puts', 'putchar', 'getc'],
    'Database Concepts': ['database', 'dbms', 'rdbms', 'table', 'record', 'field', 'tuple', 'entity', 'attribute', 'relation', 'normalization', 'schema', 'dictionary', 'redundancy', 'integrity', 'acid', 'view', 'index'],
    'Keys & Relationships': ['key', 'primary', 'foreign', 'composite', 'candidate', 'alternate', 'super', 'relationship', 'many', 'referential'],
    'MS Access': ['access', 'query', 'form', 'report', 'macro', 'module', 'objects', 'vba'],
    'Database Models': ['hierarchical', 'network', 'relational', 'model', 'tree', 'graph', 'oriented'],
    'SQL & DB Languages': ['sql', 'dml', 'ddl', 'dcl', 'tcl', 'dba', 'administrator'],
    'File Handling': ['file', 'fclose', 'fopen', 'data', 'modes', 'handling'],
    'Preprocessor & Structure': ['preprocessor', 'include', 'define', 'header', 'directive', 'structure', 'stdio', 'conio', 'math'],
    'Arrays & Pointers': ['array', 'pointer', 'address', 'strlen', 'string'],
    'Flowcharts & Algorithms': ['flowchart', 'algorithm', 'notation', 'pseudocode', 'pictorial'],
    'Errors & Debugging': ['error', 'syntax', 'runtime', 'logical', 'debug', 'compiler', 'interpreter']
}

def categorize_question(text):
    text_lower = text.lower()
    cats = []
    for cat, keywords in TOPIC_CATEGORIES.items():
        for kw in keywords:
            if kw in text_lower:
                cats.append(cat)
                break
    return cats if cats else ['Other']

topic_by_year = defaultdict(lambda: defaultdict(int))
topic_overall = Counter()
for r in rows:
    cats = categorize_question(r['question'])
    for c in cats:
        topic_by_year[r['year']][c] += 1
        topic_overall[c] += 1

# ── Prepare chart data as JSON ──
chart_data = {
    'years': years,
    'yearly_totals': [yearly_counts[y] for y in years],
    'mcqs_by_year': [type_year[y].get('MCQs', 0) for y in years],
    'short_by_year': [type_year[y].get('Short', 0) for y in years],
    'long_by_year': [type_year[y].get('Long', 0) for y in years],
    'type_totals': {t: type_total[t] for t in types},
    'keyword_labels': [k for k, v in keyword_freq[:20]],
    'keyword_values': [v for k, v in keyword_freq[:20]],
    'topic_labels': [t for t, c in topic_overall.most_common(12)],
    'topic_values': [c for t, c in topic_overall.most_common(12)],
}

# ── percentage shares per year ──
pct_by_year = {}
for y in years:
    total_y = yearly_counts[y]
    if total_y > 0:
        pct_by_year[y] = {t: round(type_year[y].get(t, 0) / total_y * 100, 1) for t in types}
    else:
        pct_by_year[y] = {t: 0 for t in types}

# ── Topic heatmap data ──
top_topics = [t for t, c in topic_overall.most_common(10)]
heatmap_data = []
for topic in top_topics:
    row_data = []
    for y in years:
        row_data.append(topic_by_year[y].get(topic, 0))
    heatmap_data.append({'topic': topic, 'values': row_data})

# ── Build HTML ──
def make_yoy_table():
    rows_html = ""
    for item in yoy:
        arrow = "↑" if item['change'] > 0 else ("↓" if item['change'] < 0 else "→")
        color = "#27ae60" if item['change'] > 0 else ("#e74c3c" if item['change'] < 0 else "#7f8c8d")
        gap_note = ""
        if item['from'] == 2019 and item['to'] == 2021:
            gap_note = ' <span style="color:#e67e22;font-size:0.85em;">(2020 missing — COVID-19)</span>'
        rows_html += f"""<tr>
            <td>{item['from']} → {item['to']}{gap_note}</td>
            <td>{item['prev']}</td>
            <td>{item['curr']}</td>
            <td style="color:{color};font-weight:600;">{arrow} {item['change']:+d}</td>
            <td style="color:{color};font-weight:600;">{item['pct']:+.1f}%</td>
        </tr>"""
    return rows_html

def make_yearly_detail_table():
    rows_html = ""
    for y in years:
        t = yearly_counts[y]
        m = type_year[y].get('MCQs', 0)
        s = type_year[y].get('Short', 0)
        l = type_year[y].get('Long', 0)
        mp = pct_by_year[y]['MCQs']
        sp = pct_by_year[y]['Short']
        lp = pct_by_year[y]['Long']
        rows_html += f"""<tr>
            <td><strong>{y}</strong></td>
            <td>{t}</td>
            <td>{m} <span class="pct">({mp}%)</span></td>
            <td>{s} <span class="pct">({sp}%)</span></td>
            <td>{l} <span class="pct">({lp}%)</span></td>
        </tr>"""
    return rows_html

def make_topic_heatmap_html():
    rows_html = ""
    for item in heatmap_data:
        max_val = max(item['values']) if item['values'] else 1
        cells = ""
        for v in item['values']:
            intensity = min(v / max(max_val, 1), 1.0)
            bg = f"rgba(52, 73, 94, {0.1 + intensity * 0.7})"
            fg = "#fff" if intensity > 0.5 else "#2c3e50"
            cells += f'<td style="background:{bg};color:{fg};text-align:center;font-weight:600;">{v}</td>'
        rows_html += f'<tr><td class="topic-label">{item["topic"]}</td>{cells}</tr>'
    return rows_html

def make_keyword_table_by_type():
    html_parts = ""
    for t in types:
        html_parts += f'<div class="keyword-col"><h4>{t}</h4><table class="mini-table"><thead><tr><th>Keyword</th><th>Freq</th></tr></thead><tbody>'
        for kw, freq in keywords_by_type[t][:12]:
            html_parts += f'<tr><td>{kw}</td><td>{freq}</td></tr>'
        html_parts += '</tbody></table></div>'
    return html_parts

# ── Compute insights ──
max_year = max(yearly_counts, key=yearly_counts.get)
min_year = min(yearly_counts, key=yearly_counts.get)
avg_questions = round(sum(yearly_counts.values()) / len(yearly_counts), 1)

# Stability analysis
mcq_pcts = [pct_by_year[y]['MCQs'] for y in years]
short_pcts = [pct_by_year[y]['Short'] for y in years]
long_pcts = [pct_by_year[y]['Long'] for y in years]

mcq_std = round((sum((x - sum(mcq_pcts)/len(mcq_pcts))**2 for x in mcq_pcts) / len(mcq_pcts))**0.5, 1)
short_std = round((sum((x - sum(short_pcts)/len(short_pcts))**2 for x in short_pcts) / len(short_pcts))**0.5, 1)
long_std = round((sum((x - sum(long_pcts)/len(long_pcts))**2 for x in long_pcts) / len(long_pcts))**0.5, 1)

# Consistently appearing topics
consistent_topics = []
for topic in top_topics:
    appear_years = sum(1 for y in years if topic_by_year[y].get(topic, 0) > 0)
    consistent_topics.append((topic, appear_years))
consistent_topics.sort(key=lambda x: -x[1])

